import Link from "next/link";
import { Suspense } from "react";
import { io } from "next/cache";
import { redirect } from "next/navigation";
import {
  ArchiveFrame,
  ArchiveLoading,
  ArchiveState,
} from "@/components/archive/archive-view";
import { loadArchive } from "@/lib/edition/archive-load";

export const metadata = {
  title: "Today’s Paper · The Morning Paper",
  robots: { index: false },
};

// Navigation destination until the existing edition layer gains persistence.
// No paper is generated by this route.
export default function TodayPage() {
  return (
    <Suspense fallback={<ArchiveLoading />}>
      <Today />
    </Suspense>
  );
}

async function Today() {
  await io();
  const result = await loadArchive();
  if (result.status === "ready" && result.data.currentEditionId) {
    redirect(`/archive/${encodeURIComponent(result.data.currentEditionId)}`);
  }
  return (
    <ArchiveFrame
      title="Today’s Paper"
      eyebrow="Your morning edition"
      description="A little perspective to start your day."
    >
      <ArchiveState kind={result.status === "error" ? "error" : "today"} />
      <Link href="/archive" className="underline underline-offset-4">
        Back to Archive
      </Link>
    </ArchiveFrame>
  );
}
